-- A database a desk on main wrote before terminology step 5 (main at dcd60b5, PRAGMA user_version 4):
-- a show with palettes, a Look and a cue with FX on every Order, a Palette Steps over two palettes,
-- a speed master with a usage, and surface bindings pressTemplate and stackEffectSize. Frozen: never
-- regenerate it from a later commit. The desk's accounts and sessions are left out.

CREATE TABLE busk_banks (id INTEGER PRIMARY KEY AUTOINCREMENT, column_id INT NOT NULL, sort_order INT NOT NULL, "name" VARCHAR(255) NOT NULL, solo BOOLEAN DEFAULT 0 NOT NULL, flow VARCHAR(16) DEFAULT 'WRAP' NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_banks_column_id__id FOREIGN KEY (column_id) REFERENCES busk_columns(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_banks_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_banks_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_columns (id INTEGER PRIMARY KEY AUTOINCREMENT, page_id INT NOT NULL, "row" INT NOT NULL, sort_order INT NOT NULL, width INT NOT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_columns_page_id__id FOREIGN KEY (page_id) REFERENCES busk_pages(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_columns_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_row CHECK ("row" BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_columns_signed_integer_width CHECK (width BETWEEN -2147483648 AND 2147483647));
CREATE TABLE busk_pads (id INTEGER PRIMARY KEY AUTOINCREMENT, bank_id INT NOT NULL, sort_order INT NOT NULL, template_id INT NULL, look_id INT NULL, cue_id INT NULL, uuid BINARY(16) NOT NULL, CONSTRAINT fk_busk_pads_bank_id__id FOREIGN KEY (bank_id) REFERENCES busk_banks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_template_id__id FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_look_id__id FOREIGN KEY (look_id) REFERENCES looks(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_busk_pads_cue_id__id FOREIGN KEY (cue_id) REFERENCES cues(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_busk_pads_signed_integer_id CHECK (id BETWEEN -2147483648 AND 2147483647), CONSTRAINT chk_busk_pads_signed_integer_sort_order CHECK (sort_order BETWEEN -2147483648 AND 2147483647), CONSTRAINT busk_pad_exactly_one_ref CHECK (((template_id IS NOT NULL) AND (look_id IS NULL) AND (cue_id IS NULL)) OR ((template_id IS NULL) AND (look_id IS NOT NULL) AND (cue_id IS NULL)) OR ((template_id IS NULL) AND (look_id IS NULL) AND (cue_id IS NOT NULL))));
